-- RC-1123, RC-1124 (RP-141): fine-tuning, behind FF_FINE_TUNING. fine_tuning_consents holds the
-- training opt-in of a project: one row per grant; a withdrawal stamps withdrawn_by and
-- withdrawn_at, and at most one grant per project is active. fine_tuning_use_cases holds a named
-- selector of a project's model calls; a name is unique among the project's use cases that are not
-- archived. Generated by drizzle-kit from views/fine-tuning/schema.ts, then written as upstream's
-- 0111 and 0112 (ratel-cloud): IF NOT EXISTS, with the foreign keys inline, so a database migrated
-- by ratel-cloud already has them and this is a no-op there. New, empty tables: no lock on a hot
-- table, nothing to backfill.
CREATE TABLE IF NOT EXISTS "fine_tuning_consents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL,
	"given_by" text NOT NULL,
	"given_at" timestamp with time zone DEFAULT now() NOT NULL,
	"text_version" text NOT NULL,
	"withdrawn_by" text,
	"withdrawn_at" timestamp with time zone,
	CONSTRAINT "fine_tuning_consents_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action
);
